def smallest_good_base(n):
    number=int(n)
    for digits in range(number.bit_length(),2,-1):
        low=2
        high=1<<((number.bit_length()+digits-2)//(digits-1))
        while low<=high:
            base=(low+high)//2
            total=1
            for _ in range(digits-1):
                total=total*base+1
                if total>number:
                    break
            if total==number:
                return str(base)
            if total<number:
                low=base+1
            else:
                high=base-1
    return str(number-1)

